"""
Generate the token_pressure_scale scenario family (tps001–tps035).

Each scenario has 20 candidate memories against a tight 400-token budget.
Only 5 of the 20 are gold-valid (critical + supporting).  The remaining 15
are noise (stale or irrelevant), testing whether the system correctly prunes
to budget without losing the critical memories.

Run from the repo root or the tools/ directory:
    python tools/generate_scale_scenarios.py
"""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCENARIOS = ROOT / "scenarios"
SCHEMA_VERSION = "mvi-scenario-v1"

_HOLDOUTS = {f"tps{n:03d}" for n in range(24, 36)}


def write(path: Path, data: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")


def mem(mid: str, tier: str, content: str, validity: str, bucket: str) -> dict:
    return {"id": mid, "tier": tier, "content": content, "validity": validity, "bucket": bucket}


def build_scale_scenario(
    sid: str,
    task: str,
    critical_s1: str,
    critical_p1: str,
    supporting_p2: str,
    supporting_l1: str,
    supporting_s2: str,
    noise: list[tuple[str, str, str, str]],  # (id_suffix, tier, content, validity)
    split: str = "public",
) -> dict:
    mems = [
        mem(f"{sid}-s1", "session",   critical_s1,  "valid", "critical"),
        mem(f"{sid}-p1", "project",   critical_p1,  "valid", "critical"),
        mem(f"{sid}-p2", "project",   supporting_p2, "valid", "supporting"),
        mem(f"{sid}-l1", "long_term", supporting_l1, "valid", "supporting"),
        mem(f"{sid}-s2", "session",   supporting_s2, "valid", "supporting"),
    ]
    for suffix, tier, content, validity in noise:
        mems.append(mem(f"{sid}-{suffix}", tier, content, validity, "supporting"))

    gold_valid  = [f"{sid}-s1", f"{sid}-p1", f"{sid}-p2", f"{sid}-l1", f"{sid}-s2"]
    gold_invalid = [f"{sid}-{s}" for s, _, _, _ in noise]

    return {
        "schema_version": SCHEMA_VERSION,
        "scenario_id": sid,
        "family": "token_pressure_scale",
        "split": split,
        "task": task,
        "repo_state_fingerprint": f"{sid}-repo-v1",
        "token_budget": 400,
        "candidate_memories": mems,
        "gold_valid_ids": gold_valid,
        "gold_invalid_ids": gold_invalid,
        "preferred_order_buckets": [
            {"name": "session_critical", "memory_ids": [f"{sid}-s1"]},
            {"name": "project_critical", "memory_ids": [f"{sid}-p1"]},
            {"name": "supporting",       "memory_ids": [f"{sid}-p2", f"{sid}-l1", f"{sid}-s2"]},
        ],
        "task_outcome_baselines": {"no_memory": 0.05, "ideal": 1.0},
    }


# Each scenario tuple:
# (sid, task, s1, p1, p2, l1, s2, noise_15)
# noise_15 is a list of 15 (suffix, tier, content, validity) tuples.

