def main() -> None:
    for entry in _SCENARIOS:
        sid    = entry[0]
        task   = entry[1]
        s1, p1, p2, l1, s2 = entry[2], entry[3], entry[4], entry[5], entry[6]
        noise  = entry[7]
        split  = "holdout" if sid in _HOLDOUTS else "public"
        sc = build_scale_scenario(sid, task, s1, p1, p2, l1, s2, noise, split)
        write(SCENARIOS / "token_pressure_scale" / f"{sid}.json", sc)

    total = len(_SCENARIOS)
    holdout_count = sum(1 for e in _SCENARIOS if e[0] in _HOLDOUTS)
    print(f"token_pressure_scale: {total} scenarios written "
          f"({total - holdout_count} public, {holdout_count} holdout).")
    print(f"Each scenario has 20 candidate memories and a 400-token budget.")


if __name__ == "__main__":
    main()
